     *
     * The associated data is not encrypted, but it is integrity-protected as part
     * of the seal operation. Any mismatch when opening must fail.
     *
     * # Errors
     *
     * Returns an error if the keystore refuses the operation or the seal fails.
     */
    @Throws(StorageException::class)override fun `seal`(`associatedData`: kotlin.ByteArray, `plaintext`: kotlin.ByteArray): kotlin.ByteArray {
            return FfiConverterByteArray.lift(
    callWithHandle {
    uniffiRustCallWithError(StorageException) { _status ->
    UniffiLib.uniffi_walletkit_core_fn_method_devicekeystore_seal(
        it,
        
        FfiConverterByteArray.lower(`associatedData`),
        FfiConverterByteArray.lower(`plaintext`),_status)
}
    }
    )
    }
    

    
    /**
     * Opens ciphertext under the device-bound key, verifying `associated_data`.
     *
     * The same associated data used during sealing must be supplied or the open
     * operation must fail.
     *
     * # Errors
     *
     * Returns an error if authentication fails or the keystore cannot open.
     */
    @Throws(StorageException::class)override fun `openSealed`(`associatedData`: kotlin.ByteArray, `ciphertext`: kotlin.ByteArray): kotlin.ByteArray {
            return FfiConverterByteArray.lift(
    callWithHandle {
    uniffiRustCallWithError(StorageException) { _status ->
    UniffiLib.uniffi_walletkit_core_fn_method_devicekeystore_open_sealed(
        it,
        
        FfiConverterByteArray.lower(`associatedData`),
        FfiConverterByteArray.lower(`ciphertext`),_status)
