 */
public object FfiConverterTypeDeviceKeystore: FfiConverter<DeviceKeystore, Long> {
    internal val handleMap = UniffiHandleMap<DeviceKeystore>()

    override fun lower(value: DeviceKeystore): Long {
        if (value is DeviceKeystoreImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): DeviceKeystore {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return DeviceKeystoreImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): DeviceKeystore {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: DeviceKeystore) = 8UL

    override fun write(value: DeviceKeystore, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


