/**
 * @suppress
 */
public object FfiConverterTypeFieldElement: FfiConverter<FieldElement, Long> {
    override fun lower(value: FieldElement): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): FieldElement {
        return FieldElement(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): FieldElement {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: FieldElement) = 8UL

    override fun write(value: FieldElement, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


