     *
     * # Errors
     * Will error if the network request fails or the gateway returns an error.
     */
    @Throws(WalletKitException::class)
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `pollStatus`() : RegistrationStatus {
        return uniffiRustCallAsync(
        callWithHandle { uniffiHandle ->
            UniffiLib.uniffi_walletkit_core_fn_method_initializingauthenticator_poll_status(
                uniffiHandle,
                
            )
        },
        { future, callback, continuation -> UniffiLib.ffi_walletkit_core_rust_future_poll_rust_buffer(future, callback, continuation) },
        { future, continuation -> UniffiLib.ffi_walletkit_core_rust_future_complete_rust_buffer(future, continuation) },
        { future -> UniffiLib.ffi_walletkit_core_rust_future_free_rust_buffer(future) },
        // lift function
        { FfiConverterTypeRegistrationStatus.lift(it) },
        // Error FFI converter
        WalletKitException.ErrorHandler,
    )
