/**
 * Error returned by [`check_credentials_against_proof_request`].
 */
sealed class CredentialConstraintsCheckException: kotlin.Exception() {
    
    /**
     * Credential store query failed.
     */
    class Storage(
        
        val v1: StorageException
        ) : CredentialConstraintsCheckException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * The constraint expression exceeds the maximum nesting depth of 2.
     */
    class ConstraintTooDeep(
        ) : CredentialConstraintsCheckException() {
        override val message
            get() = ""
    }
    
    /**
     * The constraint expression exceeds the maximum node count.
     */
    class ConstraintTooLarge(
        ) : CredentialConstraintsCheckException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CredentialConstraintsCheckException> {
        override fun lift(error_buf: RustBuffer.ByValue): CredentialConstraintsCheckException = FfiConverterTypeCredentialConstraintsCheckError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCredentialConstraintsCheckError : FfiConverterRustBuffer<CredentialConstraintsCheckException> {
    override fun read(buf: ByteBuffer): CredentialConstraintsCheckException {
        

        return when(buf.getInt()) {
            1 -> CredentialConstraintsCheckException.Storage(
                FfiConverterTypeStorageError.read(buf),
                )
            2 -> CredentialConstraintsCheckException.ConstraintTooDeep()
            3 -> CredentialConstraintsCheckException.ConstraintTooLarge()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CredentialConstraintsCheckException): ULong {
        return when(value) {
            is CredentialConstraintsCheckException.Storage -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterTypeStorageError.allocationSize(value.v1)
            )
            is CredentialConstraintsCheckException.ConstraintTooDeep -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CredentialConstraintsCheckException.ConstraintTooLarge -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: CredentialConstraintsCheckException, buf: ByteBuffer) {
        when(value) {
            is CredentialConstraintsCheckException.Storage -> {
                buf.putInt(1)
                FfiConverterTypeStorageError.write(value.v1, buf)
                Unit
            }
            is CredentialConstraintsCheckException.ConstraintTooDeep -> {
                buf.putInt(2)
                Unit
            }
            is CredentialConstraintsCheckException.ConstraintTooLarge -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



