                buf.putInt(16)
                Unit
            }
            is WalletKitException.DuplicateNonce -> {
                buf.putInt(17)
                Unit
            }
            is WalletKitException.UnknownRp -> {
                buf.putInt(18)
                Unit
            }
            is WalletKitException.InactiveRp -> {
                buf.putInt(19)
                Unit
            }
            is WalletKitException.TimestampTooOld -> {
                buf.putInt(20)
                Unit
            }
            is WalletKitException.TimestampTooFarInFuture -> {
                buf.putInt(21)
                Unit
            }
            is WalletKitException.InvalidTimestamp -> {
                buf.putInt(22)
                Unit
            }
            is WalletKitException.RpSignatureExpired -> {
                buf.putInt(23)
                Unit
            }
            is WalletKitException.Groth16MaterialCacheInvalid -> {
                buf.putInt(24)
                FfiConverterString.write(value.`path`, buf)
                FfiConverterString.write(value.`error`, buf)
                Unit
            }
            is WalletKitException.Groth16MaterialEmbeddedLoad -> {
                buf.putInt(25)
                FfiConverterString.write(value.`error`, buf)
                Unit
            }
            is WalletKitException.Generic -> {
                buf.putInt(26)
                FfiConverterString.write(value.`error`, buf)
                Unit
            }
            is WalletKitException.RecoveryBindingDoesNotExist -> {
                buf.putInt(27)
                Unit
            }
            is WalletKitException.SessionIdMismatch -> {
                buf.putInt(28)
                Unit
            }
            is WalletKitException.NfcNonRetryable -> {
                buf.putInt(29)
                FfiConverterString.write(value.`errorCode`, buf)
                Unit
            }
            is WalletKitException.DebugReportNotFound -> {
                buf.putInt(30)
                Unit
            }
            is WalletKitException.IdentityNotFound -> {
                buf.putInt(31)
                Unit
            }
            is WalletKitException.NoSuccessfulCaptureFound -> {
                buf.putInt(32)
                Unit
            }
            is WalletKitException.NotEligibleForRecovery -> {
                buf.putInt(33)
                Unit
            }
            is WalletKitException.OhttpException -> {
                buf.putInt(34)
                FfiConverterString.write(value.`error`, buf)
                Unit
            }
            is WalletKitException.InvalidActionSession -> {
                buf.putInt(35)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




