/**
 * @suppress
 */
public object FfiConverterMapUIntByteArray: FfiConverterRustBuffer<Map<kotlin.UInt, kotlin.ByteArray>> {
    override fun read(buf: ByteBuffer): Map<kotlin.UInt, kotlin.ByteArray> {
        val len = buf.getInt()
        return buildMap<kotlin.UInt, kotlin.ByteArray>(len) {
            repeat(len) {
                val k = FfiConverterUInt.read(buf)
                val v = FfiConverterByteArray.read(buf)
                this[k] = v
            }
        }
    }

    override fun allocationSize(value: Map<kotlin.UInt, kotlin.ByteArray>): ULong {
        val spaceForMapSize = 4UL
        val spaceForChildren = value.map { (k, v) ->
            FfiConverterUInt.allocationSize(k) +
            FfiConverterByteArray.allocationSize(v)
        }.sum()
        return spaceForMapSize + spaceForChildren
    }

    override fun write(value: Map<kotlin.UInt, kotlin.ByteArray>, buf: ByteBuffer) {
        buf.putInt(value.size)
        // The parens on `(k, v)` here ensure we're calling the right method,
        // which is important for compatibility with older android devices.
        // Ref https://blog.danlew.net/2017/03/16/kotlin-puzzler-whose-line-is-it-anyways/
        value.forEach { (k, v) ->
            FfiConverterUInt.write(k, buf)
            FfiConverterByteArray.write(v, buf)
        }
    }
}




