public typealias Uint256 = java.math.BigInteger

/**
 * @suppress
 */
public object FfiConverterTypeUint256: FfiConverter<Uint256, RustBuffer.ByValue> {
    override fun lift(value: RustBuffer.ByValue): Uint256 {
        val builtinValue = FfiConverterString.lift(value)
        return java.math.BigInteger(builtinValue, 16)
    }

    override fun lower(value: Uint256): RustBuffer.ByValue {
        val builtinValue = value.toString(16)
        return FfiConverterString.lower(builtinValue)
    }

    override fun read(buf: ByteBuffer): Uint256 {
        val builtinValue = FfiConverterString.read(buf)
        return java.math.BigInteger(builtinValue, 16)
    }

    override fun allocationSize(value: Uint256): ULong {
        val builtinValue = value.toString(16)
        return FfiConverterString.allocationSize(builtinValue)
    }

    override fun write(value: Uint256, buf: ByteBuffer) {
        val builtinValue = value.toString(16)
        FfiConverterString.write(builtinValue, buf)
    }
}








